manifest=read.call('source-manifest.json')
{'src/interpreter/assignment.rs'=>'rejected-assignment.rs','src/interpreter/nested_publication.rs'=>'rejected-nested-publication.rs','tests/nested_dictionary_spill_publication.rs'=>nil}.each{|p,f|raise 'Candidate source drift' unless manifest['source_hashes'][p]==sha.call(f ? d+'/'+f : p)}
